{% comment %}
  Generic product info block - for every regular shirt (not the mystery box)
  Paste into: Customize → Products → Default product template → Add block → Custom Liquid (right under the title/price area).
  Then hide the theme's Title, Price and Description blocks in that template so nothing shows twice.
  The mystery box keeps its own template/block.
  ✏️ Edit the links below.
{% endcomment %}

{%- assign link_sizes = '/pages/טבלת-מידות' -%}
{%- assign link_terms = '/pages/takanon' -%}
{%- assign link_mystery = '/pages/יוצר-מיסטרי' -%}
{%- assign link_insta = 'https://instagram.com/hanut.hashofet' -%}
{%- assign link_whatsapp = 'https://wa.me/972515310498' -%}

{%- assign cur = product.selected_or_first_available_variant -%}
{%- assign parts = product.title | split: '|' -%}
{%- assign team = parts.first | strip -%}

<style>
  .gpi {
    --ink: #121212; --muted: #666258; --sand: #efece3; --line: #e2ded3; --green: #1a9c52; --red: #d8322b;
    direction: rtl; color: var(--ink); font-family: inherit; margin: 8px 0;
  }
  .gpi a { color: inherit; }
  .gpi a:focus-visible, .gpi summary:focus-visible { outline: 2px solid var(--ink); outline-offset: 2px; border-radius: 6px; }

  /* breathing room between gallery and info (RTL fix) */
  @media screen and (min-width: 750px) { .product__info-wrapper { padding-left: 0 !important; padding-right: 5rem !important; } }
  @media screen and (min-width: 990px) { .product__info-wrapper { padding-right: 7rem !important; } }

  /* title */
  .gpi__title { margin: 0; line-height: 1.05; }
  .gpi__team { display: block; font-size: 40px; font-weight: 900; letter-spacing: -0.02em; }
  .gpi__meta { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 12px; }
  .gpi__chip {
    font-size: 16px; font-weight: 900; line-height: 1; letter-spacing: 0;
    background: #fff; color: var(--ink); border: 2px solid var(--ink);
    border-radius: 12px; padding: 8px 14px;
  }
  .gpi__chip:first-child { background: var(--ink); color: #fff; font-variant-numeric: tabular-nums; }

  /* price */
  .gpi__price { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; margin-top: 16px; }
  .gpi__now { font-size: 32px; font-weight: 900; font-variant-numeric: tabular-nums; line-height: 1; }
  .gpi__was { font-size: 17px; color: var(--muted); text-decoration: line-through; }
  .gpi__off { background: var(--red); color: #fff; font-size: 13px; font-weight: 900; padding: 5px 10px; border-radius: 100px; }
  .gpi__save { font-size: 14px; font-weight: 800; color: var(--green); }
  .gpi__was:empty, .gpi__off:empty, .gpi__save:empty { display: none; }

  /* info list */
  .gpi__list { list-style: none; margin: 22px 0 0; padding: 0; display: grid; gap: 10px; }
  .gpi__list li { display: flex; gap: 12px; align-items: flex-start; font-size: 15px; line-height: 1.5; }
  .gpi__list b { font-weight: 800; }
  .gpi__list a { font-weight: 800; text-underline-offset: 3px; }
  .gpi__ic { flex-shrink: 0; width: 30px; height: 30px; border-radius: 9px; background: var(--sand); display: flex; align-items: center; justify-content: center; }
  .gpi__ic svg { width: 17px; height: 17px; }
  .gpi__muted { color: var(--muted); font-size: 14px; }

  /* versions explainer */
  .gpi__ver { margin-top: 18px; border: 1px solid var(--line); border-radius: 16px; background: #fff; }
  .gpi__ver summary { list-style: none; cursor: pointer; padding: 14px 16px; font-weight: 800; font-size: 15px; display: flex; justify-content: space-between; align-items: center; }
  .gpi__ver summary::-webkit-details-marker { display: none; }
  .gpi__ver summary::after { content: "+"; font-size: 20px; color: var(--muted); }
  .gpi__ver[open] summary::after { content: "−"; }
  .gpi__vgrid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; padding: 0 16px 16px; }
  .gpi__vcard { background: var(--sand); border-radius: 12px; padding: 12px; font-size: 14px; line-height: 1.5; }
  .gpi__vcard b { display: block; font-size: 15px; font-weight: 900; margin-bottom: 4px; }

  /* mystery cross-sell */
  .gpi__mys {
    margin-top: 18px; display: flex; align-items: center; gap: 14px; text-decoration: none;
    background: var(--ink); color: #fff !important; border-radius: 16px; padding: 14px 16px;
    transition: transform .2s ease;
  }
  .gpi__mys:hover { transform: translateY(-2px); }
  .gpi__mys svg.box { width: 42px; height: 40px; flex-shrink: 0; }
  .gpi__mys span { flex: 1; font-size: 14px; line-height: 1.4; opacity: .9; }
  .gpi__mys span b { display: block; font-size: 16px; font-weight: 900; opacity: 1; }
  .gpi__mys i { font-style: normal; font-weight: 900; font-size: 14px; background: #fff; color: var(--ink); padding: 8px 12px; border-radius: 10px; white-space: nowrap; }

  /* trust */
  .gpi__trust { margin-top: 18px; display: grid; grid-template-columns: repeat(3, 1fr); border: 1px solid var(--line); border-radius: 16px; overflow: hidden; }
  .gpi__t { padding: 14px 8px; text-align: center; font-size: 12.5px; line-height: 1.35; text-decoration: none; }
  .gpi__t + .gpi__t { border-right: 1px solid var(--line); }
  .gpi__t svg { width: 22px; height: 22px; display: block; margin: 0 auto 6px; }
  .gpi__t b { display: block; font-size: 13.5px; font-weight: 800; }
  .gpi__t span { color: var(--muted); }
  .gpi__help { margin: 14px 0 0; font-size: 14px; color: var(--muted); text-align: center; }
  .gpi__help a { color: var(--green); font-weight: 800; text-underline-offset: 3px; }

  @media (max-width: 480px) {
    .gpi__team { font-size: 32px; }
    .gpi__chip { font-size: 15px; padding: 7px 12px; }
    .gpi__now { font-size: 28px; }
    .gpi__vgrid { grid-template-columns: 1fr; }
    .gpi__t { padding: 12px 6px; font-size: 12px; }
  }
  @media (prefers-reduced-motion: reduce) { .gpi__mys { transition: none; } }
</style>

