  </div>

  <p class="gpi__help">יש שאלה על החולצה? <a href="{{ link_whatsapp }}" target="_blank" rel="noopener">דברו איתנו בוואטסאפ</a></p>
</div>

<script type="application/json" id="gpi-variants-{{ section.id }}">
  [{%- for v in product.variants -%}{"id":{{ v.id }},"p":{{ v.price }},"c":{{ v.compare_at_price | default: 0 }}}{% unless forloop.last %},{% endunless %}{%- endfor -%}]
</script>
<script>
(function () {
  var root = document.getElementById('gpi-{{ section.id }}');
  var data = document.getElementById('gpi-variants-{{ section.id }}');
  if (!root || !data || root.dataset.ready) return;
  root.dataset.ready = '1';
  var variants = JSON.parse(data.textContent);
  var elP = root.querySelector('[data-price]'), elC = root.querySelector('[data-compare]');
  var elO = root.querySelector('[data-off]'), elS = root.querySelector('[data-save]');
  var cur = elP.textContent.trim();
  var sym = cur.replace(/[\d.,\s]/g, '') || '₪';
  var symFirst = cur.indexOf(sym) === 0;
  function fmt(c) { var n = c / 100; n = n % 1 ? n.toFixed(2) : String(n); return symFirst ? sym + n : n + sym; }
  function currentId() {
    var inp = document.querySelector('form[action*="/cart/add"] [name="id"]');
    return (inp && inp.value) || new URLSearchParams(location.search).get('variant');
  }
  function update() {
    var id = String(currentId() || '');
    var v = variants.find(function (x) { return String(x.id) === id; });
    if (!v) return;
    elP.textContent = fmt(v.p);
    var sale = v.c > v.p;
    elC.textContent = sale ? fmt(v.c) : '';
    elO.textContent = sale ? Math.floor((v.c - v.p) * 100 / v.c) + '%-' : '';
    elS.textContent = sale ? 'חוסכים ' + fmt(v.c - v.p) : '';
  }
  document.addEventListener('change', function () { setTimeout(update, 60); });
  document.addEventListener('click', function (e) { if (e.target.closest('variant-selects, variant-radios, fieldset, .product-form__input')) setTimeout(update, 80); });
  window.addEventListener('popstate', update);
})();
</script>

